import Foundation
import CryptoKit

// IoT Device Firmware - Session Management Module
// Feature flags for gradual rollout of new authentication mechanisms

struct FeatureFlags {
    static let enhancedSessionRotation = ProcessInfo.processInfo.environment["FF_SESSION_ROTATION"] == "1"
    static let strictDeviceBinding = ProcessInfo.processInfo.environment["FF_DEVICE_BINDING"] == "1"
    static let legacyCompatMode = ProcessInfo.processInfo.environment["FF_LEGACY_COMPAT"] != "0"
}

class DeviceSessionStore {
    private var sessions: [String: SessionContext] = [:]
    private let lock = NSLock()

    func store(_ context: SessionContext) {
        lock.lock()
        defer { lock.unlock() }
        sessions[context.sessionId] = context
    }

    func retrieve(_ sessionId: String) -> SessionContext? {
        lock.lock()
        defer { lock.unlock() }
        return sessions[sessionId]
    }

    func remove(_ sessionId: String) {
        lock.lock()
        defer { lock.unlock() }
        sessions.removeValue(forKey: sessionId)
    }
}

struct SessionContext {
    let sessionId: String
    let deviceFingerprint: String
    var authenticatedUser: String?
    var privilegeLevel: Int
    let createdAt: Date
    var lastActivity: Date
}

class FirmwareAuthController {
    private let sessionStore = DeviceSessionStore()
    private let sessionTimeout: TimeInterval = 3600

    // Called when device initiates connection before authentication
    func initiateSession(deviceFingerprint: String, proposedSessionId: String?) -> SessionContext {
        let sessionId: String

        if FeatureFlags.legacyCompatMode, let proposed = proposedSessionId {
            // Legacy devices may propose their own session ID for reconnection
            // When legacy compat is enabled, we log the proposed ID but always
            // generate a fresh secure session ID to prevent fixation attacks
            logLegacyReconnectAttempt(proposed: proposed, fingerprint: deviceFingerprint)
            sessionId = generateSecureSessionId()
        } else {
            sessionId = generateSecureSessionId()
        }

        let context = SessionContext(
            sessionId: sessionId,
            deviceFingerprint: deviceFingerprint,
            authenticatedUser: nil,
            privilegeLevel: 0,
            createdAt: Date(),
            lastActivity: Date()
        )

        sessionStore.store(context)
        return context
    }

    // Called after successful credential verification
    func elevateSession(sessionId: String, username: String, deviceFingerprint: String) -> SessionContext? {
        guard var context = sessionStore.retrieve(sessionId) else {
            return nil
        }

        // Verify device fingerprint matches if strict binding is enabled
        if FeatureFlags.strictDeviceBinding {
            guard context.deviceFingerprint == deviceFingerprint else {
                sessionStore.remove(sessionId)
                return nil
            }
        }

        // Apply session rotation if feature flag is enabled
        if FeatureFlags.enhancedSessionRotation {
            let rotatedContext = rotateSession(existing: context, username: username)
            return rotatedContext
        }

        // Default path: elevate existing session in place
        context.authenticatedUser = username
        context.privilegeLevel = resolvePrivilege(for: username)
        context.lastActivity = Date()
        sessionStore.store(context)
        return context
    }

    private func rotateSession(existing: SessionContext, username: String) -> SessionContext {
        // Remove old session
        sessionStore.remove(existing.sessionId)

        // Issue new session with fresh ID
        let newContext = SessionContext(
            sessionId: generateSecureSessionId(),
            deviceFingerprint: existing.deviceFingerprint,
            authenticatedUser: username,
            privilegeLevel: resolvePrivilege(for: username),
            createdAt: Date(),
            lastActivity: Date()
        )
        sessionStore.store(newContext)
        return newContext
    }

    func validateSession(sessionId: String, deviceFingerprint: String) -> SessionContext? {
        guard let context = sessionStore.retrieve(sessionId) else {
            return nil
        }

        // Check timeout
        guard Date().timeIntervalSince(context.lastActivity) < sessionTimeout else {
            sessionStore.remove(sessionId)
            return nil
        }

        // Check authentication state
        guard context.authenticatedUser != nil else {
            return nil
        }

        return context
    }

    private func generateSecureSessionId() -> String {
        var bytes = [UInt8](repeating: 0, count: 32)
        let status = SecRandomCopyBytes(kSecRandomDefault, bytes.count, &bytes)
        // Never issue a session ID from a failed RNG call: a zero-filled buffer
        // would be fully predictable and defeat session security.
        guard status == errSecSuccess else {
            fatalError("Secure random generation failed with status \(status); refusing to issue a predictable session ID")
        }
        return bytes.map { String(format: "%02x", $0) }.joined()
    }

    private func resolvePrivilege(for username: String) -> Int {
        switch username {
        case "admin": return 9
        case "operator": return 5
        default: return 1
        }
    }

    private func logLegacyReconnectAttempt(proposed: String, fingerprint: String) {
        // Audit log for monitoring legacy reconnection attempts
        let timestamp = ISO8601DateFormatter().string(from: Date())
        print("[AUDIT \(timestamp)] Legacy reconnect attempt - proposed_id_hash: \(SHA256.hash(data: Data(proposed.utf8)).description.prefix(16)), fp: \(fingerprint)")
    }
}

// MQTT message handler for IoT device communication
class DeviceMessageHandler {
    private let authController = FirmwareAuthController()

    func handleConnect(payload: [String: String]) -> [String: String] {
        let fingerprint = payload["device_fp"] ?? "unknown"
        let proposedSession = payload["session_id"]

        let session = authController.initiateSession(
            deviceFingerprint: fingerprint,
            proposedSessionId: proposedSession
        )

        return ["status": "pending_auth", "session_id": session.sessionId]
    }

    func handleAuth(payload: [String: String]) -> [String: String] {
        guard let sessionId = payload["session_id"],
              let username = payload["username"],
              let password = payload["password"],
              let fingerprint = payload["device_fp"] else {
            return ["status": "error", "message": "missing_fields"]
        }

        // Credential verification (simplified for firmware context)
        guard verifyCredentials(username: username, password: password) else {
            return ["status": "error", "message": "invalid_credentials"]
        }

        guard let elevated = authController.elevateSession(
            sessionId: sessionId,
            username: username,
            deviceFingerprint: fingerprint
        ) else {
            return ["status": "error", "message": "session_invalid"]
        }

        return ["status": "authenticated", "session_id": elevated.sessionId, "privilege": String(elevated.privilegeLevel)]
    }

    func handleCommand(payload: [String: String]) -> [String: String] {
        guard let sessionId = payload["session_id"],
              let fingerprint = payload["device_fp"],
              let command = payload["command"] else {
            return ["status": "error", "message": "missing_fields"]
        }

        guard let session = authController.validateSession(
            sessionId: sessionId,
            deviceFingerprint: fingerprint
        ) else {
            return ["status": "error", "message": "unauthorized"]
        }

        return ["status": "ok", "result": "executed_\(command)_as_\(session.authenticatedUser ?? "unknown")"]
    }

    private func verifyCredentials(username: String, password: String) -> Bool {
        // In production, this checks against secure credential store
        let stored: [String: String] = ["admin": "s3cur3P@ss!", "operator": "0p3r@t0r"]
        guard let expected = stored[username] else {
            return false
        }
        return constantTimeEquals(password, expected)
    }

    // Constant-time comparison to avoid leaking password length/content via timing.
    private func constantTimeEquals(_ a: String, _ b: String) -> Bool {
        let aBytes = Array(a.utf8)
        let bBytes = Array(b.utf8)
        var diff = aBytes.count ^ bBytes.count
        let maxLen = max(aBytes.count, bBytes.count)
        for i in 0..<maxLen {
            let av = i < aBytes.count ? Int(aBytes[i]) : 0
            let bv = i < bBytes.count ? Int(bBytes[i]) : 0
            diff |= (av ^ bv)
        }
        return diff == 0
    }
}
